import{_ as e,a,c as r,ac as l}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"Linux命令行与shell脚本编程大全（第4版）","description":"按第4版25章整理 Linux 命令行、Shell 脚本、文本处理与脚本管理导读。","frontmatter":{"title":"Linux命令行与shell脚本编程大全（第4版）","description":"按第4版25章整理 Linux 命令行、Shell 脚本、文本处理与脚本管理导读。","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"书籍导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"书单 · 计算机与软件工程 · 网络与操作系统","summary":"按第4版25章整理 Linux 命令行、Shell 脚本、文本处理与脚本管理导读。","status":"active","related":[{"title":"计算机网络基础教程（第3版）","link":"/life/personal/books/computing/network-foundations","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络简介实验手册","link":"/life/personal/books/computing/network-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络互连技术","link":"/life/personal/books/computing/internetworking","kind":"书籍导读","scope":"general","audience":"general"},{"title":"网络技术教程","link":"/life/personal/books/computing/network-technology","kind":"书籍导读","scope":"general","audience":"general"},{"title":"思科网络技术学院教程 路由和交换基础实验手册","link":"/life/personal/books/computing/cisco-routing-switching-lab","kind":"书籍导读","scope":"general","audience":"general"},{"title":"计算机网络原理","link":"/life/personal/books/computing/network-principles","kind":"书籍导读","scope":"general","audience":"general"},{"title":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65","kind":"书籍导读","scope":"general","audience":"general"}],"prev":{"text":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Red Hat Enterprise Linux 6.5 系统管理","link":"/life/personal/books/computing/rhel-65"},"next":false},"headers":[],"relativePath":"life/personal/books/computing/linux-shell.md","filePath":"life/personal/books/computing/linux-shell.md"}'),n={name:"life/personal/books/computing/linux-shell.md"};function i(d,t,o,s,h,p){return a(),r("div",null,[...t[0]||(t[0]=[l('<h1 id="linux命令行与shell脚本编程大全-第4版" tabindex="-1">Linux命令行与shell脚本编程大全（第4版） <a class="header-anchor" href="#linux命令行与shell脚本编程大全-第4版" aria-label="Permalink to &quot;Linux命令行与shell脚本编程大全（第4版）&quot;">​</a></h1><p><a href="./../overview">返回分类书单</a></p><p><strong>分类：计算机与软件工程 / 网络与操作系统</strong></p><h2 id="书籍简介" tabindex="-1">书籍简介 <a class="header-anchor" href="#书籍简介" aria-label="Permalink to &quot;书籍简介&quot;">​</a></h2><p>这本书适合希望从“手动敲命令”进步到“编写可重复执行的自动化脚本”的读者。核心阅读任务是理解 Shell 如何处理参数、引用、变量、退出状态、重定向与管道，再用这些规则组织批处理工作。</p><p>命令行基础和脚本编程应该交替练习：先把一个小任务手动完成，再加入参数检查、错误处理和运行记录，观察自动化之后新增了哪些失败方式。</p><h2 id="版本说明" tabindex="-1">版本说明 <a class="header-anchor" href="#版本说明" aria-label="Permalink to &quot;版本说明&quot;">​</a></h2><p>本页对应 Richard Blum、Christine Bresnahan 合著、门佳翻译的第4版，人民邮电出版社 2022 年出版，ISBN <strong>9787115592514</strong>。根据该 ISBN 的公开书目目录整理 25 章与两个附录；本次未能直接读取 Wiley 与图灵的完整目录，因此目录来源明确采用下方的中文书目记录。实际印次和勘误以纸书为准。</p><h2 id="作者与背景" tabindex="-1">作者与背景 <a class="header-anchor" href="#作者与背景" aria-label="Permalink to &quot;作者与背景&quot;">​</a></h2><p>作者为 Richard Blum、Christine Bresnahan。Wiley 的英文第4版页面介绍 Blum 的系统与网络管理经验及 Linux 写作教学经历，并介绍 Bresnahan 的高校 Linux 认证课程教学背景。两人的实践与教学取向符合本书从命令行到脚本工具的组织方式；这些是出版社刊载的背景，不是对作者当前任职的独立调查。</p><h2 id="目标读者" tabindex="-1">目标读者 <a class="header-anchor" href="#目标读者" aria-label="Permalink to &quot;目标读者&quot;">​</a></h2><p>适合开始使用 Linux、需要把手工任务变成脚本的开发者、管理员与技术学生。已有脚本经验者可以重点读展开、文件描述符、信号与文本处理；需要严格 POSIX 可移植性的人应额外核对 shell 差异。</p><h2 id="章节介绍" tabindex="-1">章节介绍 <a class="header-anchor" href="#章节介绍" aria-label="Permalink to &quot;章节介绍&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>学习重点与可完成的练习</th></tr></thead><tbody><tr><td>第1章 初识 Linux shell</td><td>认识内核、GNU 工具、桌面环境与发行版之间的关系。</td></tr><tr><td>第2章 走进 shell</td><td>比较控制台与图形终端，建立进入命令行和管理终端的基本能力。</td></tr><tr><td>第3章 bash shell 基础命令</td><td>学习路径、文件和目录操作，通过手册确认命令行为。</td></tr><tr><td>第4章 更多的 bash shell 命令</td><td>检查进程和磁盘，使用排序、搜索、压缩与归档处理数据。</td></tr><tr><td>第5章 理解 shell</td><td>认识父子 shell、子进程以及内建命令与外部命令的差异。</td></tr><tr><td>第6章 Linux 环境变量</td><td>理解变量作用范围、PATH、启动文件与不同运行模式。</td></tr><tr><td>第7章 理解 Linux 文件权限</td><td>将用户、组、权限位和访问控制列表连接到实际访问判断。</td></tr><tr><td>第8章 管理文件系统</td><td>介绍分区、文件系统与逻辑卷，理解存储组织和维护步骤。</td></tr><tr><td>第9章 安装软件</td><td>比较发行版包管理、容器化软件分发和源码安装的使用方式。</td></tr><tr><td>第10章 文本编辑器</td><td>认识终端与图形编辑器，建立编写和修改配置、脚本的工作环境。</td></tr><tr><td>第11章 构建基础脚本</td><td>将命令、变量、替换、重定向、管道与退出状态组成脚本。</td></tr><tr><td>第12章 结构化命令</td><td>用条件判断、test 和 case 组织分支，区分数值、字符串与文件测试。</td></tr><tr><td>第13章 更多的结构化命令</td><td>介绍循环、字段分隔、嵌套及控制语句，处理批量任务。</td></tr><tr><td>第14章 处理用户输入</td><td>读取位置参数、命令选项与交互输入，形成清楚的脚本接口。</td></tr><tr><td>第15章 呈现数据</td><td>管理标准流、自定义文件描述符、临时文件与日志输出。</td></tr><tr><td>第16章 脚本控制</td><td>处理信号、后台任务、优先级与定时执行，检查脚本退出行为。</td></tr><tr><td>第17章 创建函数</td><td>组织参数、返回状态、局部变量和函数库，理解作用范围。</td></tr><tr><td>第18章 图形化桌面环境中的脚本编程</td><td>用文本菜单、dialog 和桌面窗口部件构造简单交互界面。</td></tr><tr><td>第19章 初识 sed 和 gawk</td><td>学习流式文本处理、替换和记录操作，建立批处理基础。</td></tr><tr><td>第20章 正则表达式</td><td>比较基本与扩展正则，理解匹配、锚点、分组和重复。</td></tr><tr><td>第21章 sed 进阶</td><td>使用多行处理、保留空间和流程控制完成较复杂文本变换。</td></tr><tr><td>第22章 gawk 进阶</td><td>将变量、数组、模式、函数与格式化输出组合成数据处理程序。</td></tr><tr><td>第23章 使用其他 shell</td><td>认识 dash 与 zsh 的特性，检查脚本可移植性的限制。</td></tr><tr><td>第24章 编写简单的脚本实用工具</td><td>通过备份、账户处理和系统监控整合前面的方法。</td></tr><tr><td>第25章 井井有条</td><td>使用 Git 理解工作目录、暂存区、提交和分支，管理脚本演进。</td></tr><tr><td>附录 A、B</td><td>分别提供 bash 命令与 sed、gawk 的快速查询资料。</td></tr></tbody></table><h2 id="读后感" tabindex="-1">读后感 <a class="header-anchor" href="#读后感" aria-label="Permalink to &quot;读后感&quot;">​</a></h2><p>以下为本站阅读评析，用可实践的阅读目标表达收获，不代表书单提供者已经读完、任职或完成相应项目。版本未明时，评析只针对本页明确标注的主题或参考版本。</p><h3 id="金句摘抄或阅读提炼" tabindex="-1">金句摘抄或阅读提炼 <a class="header-anchor" href="#金句摘抄或阅读提炼" aria-label="Permalink to &quot;金句摘抄或阅读提炼&quot;">​</a></h3><blockquote><p>脚本的可靠性，常常藏在引号和退出状态里。</p></blockquote><p>这是本站原创阅读提炼，不是原书引文；没有可核对页码的原文不作逐字摘抄。</p><h3 id="个人收获" tabindex="-1">个人收获 <a class="header-anchor" href="#个人收获" aria-label="Permalink to &quot;个人收获&quot;">​</a></h3><p>把一个只在当前终端成功的脚本放到干净环境中检查：工作目录、PATH、输入含空格、空变量及失败退出分别怎样影响结果。能把这些条件写成明确接口，比累积大量命令别名更有用。</p><h3 id="客观评价与阅读建议" tabindex="-1">客观评价与阅读建议 <a class="header-anchor" href="#客观评价与阅读建议" aria-label="Permalink to &quot;客观评价与阅读建议&quot;">​</a></h3><p>从基础覆盖到 sed、gawk 和脚本管理，便于按需查阅，但容易被当作语法百科逐页记忆。建议围绕一个小型报表或文件整理任务练习，先检查输入边界，再处理失败；静态检查不能替代真实运行。</p><p><strong>推荐语（本站原创，非原书引用）：</strong> 推荐给想减少重复操作的人：读完后能写出别人也能安全调用的小脚本，比记住更多命令选项更实在。</p><h2 id="来源与核对入口" tabindex="-1">来源与核对入口 <a class="header-anchor" href="#来源与核对入口" aria-label="Permalink to &quot;来源与核对入口&quot;">​</a></h2><ul><li><a href="https://book.douban.com/subject/35933905/" target="_blank" rel="noopener noreferrer">第4版中文书目与完整目录</a>：作者、ISBN 与 25 章结构的核对来源。</li><li><a href="https://www.wiley.com/en-us/Linux+Command+Line+and+Shell+Scripting+Bible%2C+4th+Edition-p-9781119700913" target="_blank" rel="noopener noreferrer">Wiley 英文第4版书目入口</a>：本次页面限制访问，未作为已读取目录的证据。</li><li><a href="https://www.gnu.org/software/bash/manual/bash.html" target="_blank" rel="noopener noreferrer">GNU Bash 手册</a>：Shell 展开、重定向与执行语义的补充参考。</li><li><a href="https://www.shellcheck.net/" target="_blank" rel="noopener noreferrer">ShellCheck</a>：脚本静态检查工具；检查结果不能替代实际运行验证。</li><li><a href="https://uat.store.wiley.com/en-us/linux-command-line-and-shell-scripting-bible-4th-edition-p-9781119700937" target="_blank" rel="noopener noreferrer">Wiley：英文第4版作者与版本信息</a>：本次可读取作者介绍；该页电子版 ISBN 不替代中文纸书 ISBN。</li></ul>',26)])])}const k=e(n,[["render",i]]);export{c as __pageData,k as default};
